//! 🧫️ Explicit shared native fixture for the two actual procedural persisted type pairs.
use semio_framework_artifact_flow_flow::{FlowHostSnapshot,Widget};
use semio_framework_artifact_playbook_playbook::{GenerationPlayRoot,GenerationPlayState};
use semio_framework_os_kernel::{DslValue,FromValue};
use semio_framework_os_kernel::os_dsl::schema::Number;
fn word(v:&serde_json::Value)->f64{f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap())}
fn answer(v:&serde_json::Value)->DslValue{match v["kind"].as_str().unwrap(){"null"=>DslValue::Null,"boolean"=>DslValue::Bool(v["value"].as_bool().unwrap()),"unsigned"=>DslValue::Number(Number::UInt(v["value"].as_str().unwrap().parse().unwrap())),"integer"=>DslValue::Number(Number::Int(v["value"].as_str().unwrap().parse().unwrap())),"float"=>DslValue::Number(Number::Float(word(&v["bits"]))),"string"=>DslValue::String(v["value"].as_str().unwrap().into()),"bytes"=>{let s=v["hex"].as_str().unwrap();DslValue::Bytes(s.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect())},"array"=>DslValue::Array(v["values"].as_array().unwrap().iter().map(answer).collect()),"object"=>DslValue::Object(v["members"].as_array().unwrap().iter().map(|m|(m["key"].as_str().unwrap().into(),answer(&m["value"]))).collect()),_=>panic!("fixture intrinsic value kind")}}
/// 📸️ Constructs every declared owned field using its native type boundary, preserving exact scalar words.
pub fn fixture(source:&str)->(FlowHostSnapshot,GenerationPlayRoot){let f:serde_json::Value=serde_json::from_str(source).unwrap();let mut host=FlowHostSnapshot::from_value(f["hostSnapshot"].clone().into()).unwrap();let words=&f["words"];host.camera.x=word(&words[0]);host.camera.y=word(&words[1]);host.camera.zoom=word(&words[2]);for widget in &mut host.widgets{if let Widget::InputSlider{value,min,max,step,..}=widget{*value=word(&words[3]);*min=word(&words[4]);*max=word(&words[5]);*step=word(&words[6]);}}let mut generation=GenerationPlayState::from_value(f["generation"].clone().into()).unwrap();generation.generations[1].values.clear();for a in f["answers"].as_array().unwrap(){generation.generations[1].values.insert(a["key"].as_str().unwrap().into(),answer(a));}(host,generation.into())}
